    }
};

class Solution {
public:
    int countPrimes(int n) {
        if (n < 3) {
            return 0;
        }
        vector<int> primes(1, 2);
        int i = 3;
        while (i < n) {
            bool prime = true;
            for (auto it : primes) {
                if (i % it == 0) {
                    prime = false;
                    break;
                }
            }
            if (prime) {
                primes.push_back(i);
            }
            i++;
        }
        return primes.size();
    }
};

