    int pivotIndex(vector<int>& nums) {
        int sumr = 0;
        int suml = 0;
        for(auto it:nums){
            sumr+=it;
        }
        int n = nums.size();
        for(int i=0; i<n; i++){
            sumr-=nums[i];
            if(sumr == suml){
                return i;
            }
            suml+=nums[i];
        }
        return -1;
    }
};

class Solution {
public:
    int sumFourDivisors(vector<int>& nums) {
        unordered_map<int, int> freq;
        unordered_map<int, int> sums;
        for (auto it : nums) {
            freq[it]++;
            if (!sums.contains(it)) {
                int i = 2;
                int j = floor(abs(sqrt(it)));

                unordered_set<int> divisors;
                while (i <= j) {
                    if (it % i == 0) {
                        divisors.insert(i);
                        divisors.insert(it / i);
                    }
                    i++;
                }
                sums[it] = 0;
                if (divisors.size() == 2) {
                    sums[it] = 1 + it;
                    for (auto dt : divisors) {
                        sums[it] += dt;
                    }
                }
            }
        }
        int ans = 0;
        for (auto it : sums) {
            int sum = it.second;
            if (sum > 0) {
                ans += freq[it.first] * sum;
            }
        }
        return ans;
    }
};

class Solution {
public:
    vector<vector<int>> insert(vector<vector<int>>& intervals, vector<int>& newInterval) {

        intervals.push_back(newInterval);

        sort(intervals.begin(), intervals.end(), [](const vector<int>& a, const vector<int>& b){
            if(a[0] == b[0]){
                return a[1] < b[1];
            }
            return a[0] < b[0];
        });

        vector<vector<int>> ans;
        int x = intervals[0][0];
        int y = intervals[0][1];

        for(auto inter: intervals){
            int x1 = inter[0];
            int y1 = inter[1];
            if(y < x1){
                ans.push_back({x,y});
                x = x1;
                y = y1;
            }else {
                x = min(x,x1);
                y = max(y,y1);
            }
        }
        ans.push_back({x,y});

        return ans;

    }
};

