class Solution {
public:
    int firstBadVersion(int n) {
        int i = 1, j = n;
        int bv = 0;
        while (i <= j) {
            int k = i + (j - i) / 2;
            bool isBad = isBadVersion(k);
            if (isBad) {
                bv = k;
                j = k - 1;
            } else {
                if (bv > 0) {
                    break;
                } else {
                    i = k + 1;
                }
            }
        }
        return bv;
    }
};

class Solution {
public:
    int mySqrt(int x) {
        if (x < 2) {
            return x;
        }
        int i = 1, j = x;
        while (i <= j) {
            long long k = i + (j - i) / 2;
            if (k * k <= x && (k + 1) * (k + 1) > x) {
                return k;
            } else if (k * k > x) {
                j = k - 1;
            } else {
                i = k + 1;
            }
        }
        return x;
    }
};

class Solution {
public:
    bool isPerfectSquare(int num) {
        if (num == 1) {
            return true;
        }

        int i = 2, j = num - 1;

        while (i <= j) {

            long long k = i + (j - i) / 2;
            long long sq = k * k;

            if (sq == num) {
                return true;
            } else if (sq > num) {
                j = k - 1;
            } else {
                i = k + 1;
            }
        }
        return false;
    }
};

class Solution {
public:
    bool buddyStrings(string s, string goal) {
        int n = s.size();

        vector<int> freq(26, 0);
        bool flag = false;

        if (goal.size() != n) {
            return false;
        }
        vector<int> diff;
        int i = 0;
        while (i < n) {
            if (s[i] != goal[i]) {
                diff.push_back(i);
            }
            freq[s[i] - 'a']++;
            if (freq[s[i] - 'a'] > 1) {
                flag = true;
            }
            i++;
        }
        if (diff.size() == 0) {
            return flag;
        }
        if (diff.size() == 2) {
            int j = diff[0], k = diff[1];
            return s[j] == goal[k] && goal[j] == s[k];
        }
        return false;
    }
};

