class Solution {
public:
    bool wordPattern(string pattern, string s) {
        int i = -1, j = -1, n = s.size(), m = pattern.size();
        vector<string> words;
        for(int k = 0; k < n; k++){
            if(s[k] != ' '){
                if(i == -1){
                    if(k == 0){
                        i = k;
                    }
                    if(k > 0 && s[k-1] == ' '){
                        i = k;
                    }
                }
                if(j == -1){
                    if(k == n-1){
                        j = k;
                    }
                    if(k < n-1 && s[k+1] == ' '){
                        j = k;
                    }
                }
            }
            if(i >= 0 && j >= 0){
                words.push_back(s.substr(i, j - i + 1));
                i = -1; j = -1;
            }
        }
        if(words.size() != m){
            return false;
        }

        unordered_map<string,char> mpsc;
        unordered_map<char,string> mpcs;

        for(int i = 0; i < m; i++){
            char ch = pattern[i];
            string word = words[i];
            if(mpcs.contains(ch) && mpcs[ch] != word){
                return false;
            }
            mpcs[ch] = word;
            if(mpsc.contains(word) && mpsc[word] != ch){
                return false;
            }
            mpsc[word] = ch;
        }

        return true;
    }
};

