class Solution {
public:
    void transpose(vector<vector<int>>& matrix) {
        int n = matrix.size();
        vector<vector<int>> trans(n, vector<int>(n, 0));
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                trans[i][j] = matrix[j][i];
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                matrix[i][j] = trans[i][j];
            }
        }
    }
    void hflip(vector<vector<int>>& matrix) {
        int n = matrix.size();
        for (auto& arr : matrix) {
            for (int i = 0; i < n / 2; i++) {
                int temp = arr[i];
                arr[i] = arr[n - 1 - i];
                arr[n - 1 - i] = temp;
            }
        }
    }

    void rotate(vector<vector<int>>& matrix) {
        transpose(matrix);
        hflip(matrix);
    }
};

class Solution {
public:
    bool searchMatrix(vector<vector<int>>& matrix, int target) {
        int n = matrix.size();
        int m = matrix[0].size();

        int i1 = 0, i2 = 0, j1 = n-1, j2 = m-1;

        while(i1 <= j1 && i1 + i2 <= j1 + j2){
            int k1 = (i1 + j1)/2, k2 = (i2 + j2)/2;
            if(matrix[k1][k2] == target){
                return true;
            }
            if(matrix[k1][k2] < target){
                if(k2 == m-1){
                    i1 = k1 + 1;
                    i2 = 0;
                }else{
                    i1 = k1;
                    i2 = k2 + 1;
                }
            }else{
                if(k2 == 0){
                    j1 = k1 - 1;
                    j2 = 0;
                }else{
                    j1 = k1;
                    j2 = k2 - 1;
                }

            }
        }
        return false;
    }
};

