class MyQueue {
    stack<int> base;
    stack<int> helper;

public:
    MyQueue() {}

    void push(int x) {
        while (!base.empty()) {
            helper.push(base.top());
            base.pop();
        }
        base.push(x);
        while (!helper.empty()) {
            base.push(helper.top());
            helper.pop();
        }
    }

    int pop() {
        while (!base.empty()) {
            helper.push(base.top());
            base.pop();
        }
        int ans = helper.top();
        helper.pop();
        while (!helper.empty()) {
            base.push(helper.top());
            helper.pop();
        }
        return ans;
    }

    int peek() {
        while (!base.empty()) {
            helper.push(base.top());
            base.pop();
        }
        int ans = helper.top();
        while (!helper.empty()) {
            base.push(helper.top());
            helper.pop();
        }
        return ans;
    }

    bool empty() { return base.empty(); }
};

