        int n = s.size();
        int j = -1;
        int k = -1;
        int i = n-1;
        while(i >= 0){
            if(s[i] != ' '){
                j = i;
                break;
            }
            i--;
        }
        if(j == -1){
            return 0;
        }
        i = j-1;
