class Solution {
public:
    int removeElement(vector<int>& nums, int val) {
        int i = 0, j = nums.size() - 1, k = 0;
        while (i < j) {
            if (nums[i] == val && nums[j] != val) {
                int temp = nums[i];
                nums[i] = nums[j];
                nums[j] = temp;
            }
            while (nums[i] != val) {
                i++;
            }
            while (nums[j] == val) {
                j--;
            }
        }
        while (nums[k] != val) {
            k++;
        }
        return k;
    }
